def findTheString(lcp):
    n = len(lcp)
    # Step 1: Build group components -- indices needing the same letter
    parent = list(range(n))
    def find(x):
        while parent[x] != x:
            parent[x] = parent[parent[x]]
            x = parent[x]
        return x
    def union(x, y):
        px, py = find(x), find(y)
        if px != py:
            parent[py] = px

    # If lcp[i][j] > 0, then s[i] == s[j]
    for i in range(n):
        for j in range(n):
            if lcp[i][j] > 0:
                union(i, j)

    # Assign characters to groups, using lexicographically smallest possible letters
    groups = {}
    ch = ord('a')
    res = [''] * n
    for i in range(n):
        g = find(i)
        if g not in groups:
            if ch > ord('z'):
                return ""
            groups[g] = chr(ch)
            ch += 1
        res[i] = groups[g]

    s = ''.join(res)
    # Step 2: Validate s against lcp using the recurrence
    # lcp[i][j] = 1 + lcp[i+1][j+1] if s[i] == s[j], else 0
    for i in range(n - 1, -1, -1):
        for j in range(n - 1, -1, -1):
            if s[i] == s[j]:
                expected = 1 + (lcp[i + 1][j + 1] if i + 1 < n and j + 1 < n else 0)
            else:
                expected = 0
            if lcp[i][j] != expected:
                return ""
    return s
